  'Throw this sheet away?': { de: 'Dieses Blatt wegwerfen?', fr: 'Jeter cette feuille ?', es: '¿Tirar esta hoja?', ja: 'この シートを すてますか？', ar: "هل ترمي هذه الورقة؟" },
  'Which page from My Notes?': { de: 'Welche Seite aus Meine Notizen?', fr: 'Quelle page de Mes notes ?', es: '¿Qué página de Mis notas?', ja: 'わたしのメモの どの ページ？', ar: "أي صفحة من «ملاحظاتي»؟" },
  'a friend': { de: 'ein Freund', fr: 'un ami', es: 'un amigo', ja: 'ともだち', ar: "صديق" },
  'A sheet for you from {name}. Open the file in Coro to put it in Things to share.': { de: 'Ein Blatt für dich von {name}. Öffne die Datei in Coro, um es in Zum Teilen zu legen.', fr: 'Une feuille pour toi de {name}. Ouvre le fichier dans Coro pour la ranger dans À partager.', es: 'Una hoja para ti de {name}. Abre el archivo en Coro para guardarla en Para compartir.', ja: '{name}から シートが とどいたよ。Coroで ひらくと シェアするものに はいります。', ar: "ورقة لك من {name}. افتح الملف في Coro لتضعها في «أشياء للمشاركة»." },
  'My Notes has no pages to send yet.': { de: 'In Meine Notizen gibt es noch keine Seiten zum Schicken.', fr: 'Mes notes n’ont pas encore de page à envoyer.', es: 'Mis notas aún no tienen páginas para enviar.', ja: '「わたしのメモ」に まだ おくれる ページが ありません。', ar: 'لا توجد في «ملاحظاتي» صفحات لإرسالها بعد.' },
  'Sending a sheet opens your phone’s messages and email.': { de: 'Ein Blatt zu schicken öffnet Nachrichten und E-Mail.', fr: 'Envoyer une feuille ouvre les messages et l’e-mail du téléphone.', es: 'Enviar una hoja abre los mensajes y el correo del teléfono.', ja: 'シートを おくると メッセージや メールが ひらきます。', ar: "إرسال ورقة يفتح الرسائل والبريد الإلكتروني في هاتفك." },
  '{name} sent you a sheet': { de: '{name} hat dir ein Blatt geschickt', fr: '{name} t’a envoyé une feuille', es: '{name} te ha enviado una hoja', ja: '{name}が シートを おくってくれたよ', ar: "أرسل لك {name} ورقة" },
  'Someone': { de: 'Jemand', fr: 'Quelqu’un', es: 'Alguien', ja: 'だれか', ar: "شخص ما" },
  'Put it in Things to share?': { de: 'In Zum Teilen legen?', fr: 'La ranger dans À partager ?', es: '¿Guardarla en Para compartir?', ja: 'シェアするものに いれますか？', ar: "هل تضعها في «أشياء للمشاركة»؟" },
  'It’s in Things to share.': { de: 'Es ist in Zum Teilen.', fr: 'C’est dans À partager.', es: 'Está en Para compartir.', ja: 'シェアするものに はいりました。', ar: "إنها في «أشياء للمشاركة»." },
  'Pin notes and photos here': { de: 'Häng hier Zettel und Fotos auf', fr: 'Épingle ici des mots et des photos', es: 'Clava aquí notas y fotos', ja: 'ここに メモや しゃしんを はろう', ar: "ثبّت الملاحظات والصور هنا" },
  'Pin something': { de: 'Etwas anpinnen', fr: 'Épingler quelque chose', es: 'Clavar algo', ja: 'なにかを はる', ar: "ثبّت شيئًا" },
  'A sticky note': { de: 'Ein Klebezettel', fr: 'Un post-it', es: 'Una nota adhesiva', ja: 'ふせん', ar: "ورقة لاصقة" },
