  'Pin it': { de: 'Anpinnen', fr: 'Épingler', es: 'Clavarla', ja: 'はる', ar: "ثبّتها" },
  'Take it down': { de: 'Abnehmen', fr: 'Retirer', es: 'Quitarla', ja: 'はがす', ar: "انزعها" },
