  'Colour behind the lines': { de: 'Hinter den Linien ausmalen', fr: 'Colorier derrière les traits', es: 'Colorear detrás de las líneas', ja: 'せんの うしろに ぬる', ar: 'لوّن خلف الخطوط' },
  'Draw on top again': { de: 'Wieder obendrauf malen', fr: 'Dessiner à nouveau par-dessus', es: 'Volver a dibujar encima', ja: 'うえに かくに もどる', ar: 'ارسم في الأعلى مجددًا' },
  "Stamps": { de: "Stempel", fr: "Tampons", es: "Sellos", ja: "スタンプ", ar: "أختام" },
  "Put the stamp away": { de: "Stempel weglegen", fr: "Ranger le tampon", es: "Guardar el sello", ja: "スタンプを しまう", ar: "ضع الختم جانبًا" },
