  "Coro in sunglasses": { de: "Coro mit Sonnenbrille", fr: "Coro en lunettes de soleil", es: "Coro con gafas de sol", ja: "サングラスの コロ", ar: "كورو بنظارة شمسية" },
  "Blue friend": { de: "Blauer Freund", fr: "Ami bleu", es: "Amigo azul", ja: "あおい ともだち", ar: "الصديق الأزرق" },
