  // ---- About ----
  'Coro is always looking for new picture books. If you’ve written or illustrated a story, send it to us and join the Coro author community. Visit corobooks.com for more information.': {
    de: 'Coro sucht immer neue Bilderbücher. Wenn du eine Geschichte geschrieben oder illustriert hast, schick sie uns und werde Teil der Coro-Autorengemeinschaft. Mehr auf corobooks.com.',
    fr: 'Coro cherche toujours de nouveaux albums. Si vous avez écrit ou illustré une histoire, envoyez-la-nous et rejoignez la communauté d’auteurs Coro. Plus d’informations sur corobooks.com.',
    es: 'Coro siempre busca nuevos libros ilustrados. Si has escrito o ilustrado un cuento, envíanoslo y únete a la comunidad de autores de Coro. Más información en corobooks.com.',
    ja: 'Coroは、いつもあたらしいえほんをさがしています。お話をかいたり、えをかいたりしたら、ぜひおくってください。Coroの作家のなかまになりませんか。くわしくはcorobooks.comへ。', ar: "تبحث Coro دائمًا عن كتب مصوّرة جديدة. إذا كتبت قصة أو رسمتها، فأرسلها إلينا وانضم إلى مجتمع مؤلفي Coro. زر corobooks.com لمزيد من المعلومات." },
  'Version {v}': { de: 'Version {v}', fr: 'Version {v}', es: 'Versión {v}', ja: 'バージョン {v}', ar: "الإصدار {v}" },
  // ---- badges ----
  'A new badge, {name}! See it in My Notes.': { de: 'Ein neues Abzeichen, {name}! Schau es dir in Meine Notizen an.', fr: 'Un nouveau badge, {name} ! Va le voir dans Mes notes.', es: '¡Una insignia nueva, {name}! Mírala en Mis notas.', ja: 'あたらしいバッジ「{name}」! わたしの メモで見てね。', ar: "وسام جديد: {name}! شاهده في «ملاحظاتي»." },
  'New badges! {name} and more. See them in My Notes.': { de: 'Neue Abzeichen! {name} und mehr. Schau sie dir in Meine Notizen an.', fr: 'Nouveaux badges ! {name} et d’autres. Va les voir dans Mes notes.', es: '¡Nuevas insignias! {name} y más. Míralas en Mis notas.', ja: 'あたらしいバッジ!{name}など。わたしの メモで見てね。', ar: "أوسمة جديدة! {name} وغيره. شاهدها في «ملاحظاتي»." },
  'First Book': { de: 'Erstes Buch', fr: 'Premier livre', es: 'Primer libro', ja: 'はじめての本', ar: "الكتاب الأول" },
  'Read a book all the way to The End.': { de: 'Lies ein Buch bis zum Ende.', fr: 'Lis un livre jusqu’à la fin.', es: 'Lee un libro hasta el final.', ja: '本をさいごまでよもう。', ar: "اقرأ كتابًا حتى النهاية." },
  'Bookworm': { de: 'Bücherwurm', fr: 'Rat de bibliothèque', es: 'Ratón de biblioteca', ja: '本のむし', ar: "دودة الكتب" },
  'Finish 5 different books.': { de: 'Lies 5 verschiedene Bücher zu Ende.', fr: 'Finis 5 livres différents.', es: 'Termina 5 libros distintos.', ja: 'ちがう本を5さつよもう。', ar: "أنهِ 5 كتب مختلفة." },
  'Story Explorer': { de: 'Geschichten-Entdecker', fr: 'Explorateur d’histoires', es: 'Explorador de cuentos', ja: 'お話たんけんか', ar: "مستكشف القصص" },
  'Finish 10 different books.': { de: 'Lies 10 verschiedene Bücher zu Ende.', fr: 'Finis 10 livres différents.', es: 'Termina 10 libros distintos.', ja: 'ちがう本を10さつよもう。', ar: "أنهِ 10 كتب مختلفة." },
  'Super Reader': { de: 'Super-Leser', fr: 'Super lecteur', es: 'Superlector', ja: 'スーパーよみて', ar: "قارئ خارق" },
  'Finish 25 different books.': { de: 'Lies 25 verschiedene Bücher zu Ende.', fr: 'Finis 25 livres différents.', es: 'Termina 25 libros distintos.', ja: 'ちがう本を25さつよもう。', ar: "أنهِ 25 كتابًا مختلفًا." },
  'Book Champ': { de: 'Bücher-Champion', fr: 'Champion des livres', es: 'Campeón de libros', ja: '本のチャンピオン', ar: "بطل الكتب" },
  'Finish 50 different books.': { de: 'Lies 50 verschiedene Bücher zu Ende.', fr: 'Finis 50 livres différents.', es: 'Termina 50 libros distintos.', ja: 'ちがう本を50さつよもう。', ar: "أنهِ 50 كتابًا مختلفًا." },
  '3 Days in a Row': { de: '3 Tage am Stück', fr: '3 jours d’affilée', es: '3 días seguidos', ja: '3日れんぞく', ar: "3 أيام متتالية" },
  'Read on 3 days in a row.': { de: 'Lies an 3 Tagen hintereinander.', fr: 'Lis 3 jours d’affilée.', es: 'Lee 3 días seguidos.', ja: '3日つづけてよもう。', ar: "اقرأ 3 أيام متتالية." },
  'A Whole Week': { de: 'Eine ganze Woche', fr: 'Toute une semaine', es: 'Una semana entera', ja: 'まるいっしゅうかん', ar: "أسبوع كامل" },
  'Read every day for a week.': { de: 'Lies eine Woche lang jeden Tag.', fr: 'Lis tous les jours pendant une semaine.', es: 'Lee todos los días durante una semana.', ja: '1しゅうかん、まいにちよもう。', ar: "اقرأ كل يوم لمدة أسبوع." },
  'A Whole Month': { de: 'Ein ganzer Monat', fr: 'Tout un mois', es: 'Un mes entero', ja: 'まるいっかげつ', ar: "شهر كامل" },
  'Read every day for 30 days.': { de: 'Lies 30 Tage lang jeden Tag.', fr: 'Lis tous les jours pendant 30 jours.', es: 'Lee todos los días durante 30 días.', ja: '30日間、まいにちよもう。', ar: "اقرأ كل يوم لمدة 30 يومًا." },
  'First Recording': { de: 'Erste Aufnahme', fr: 'Premier enregistrement', es: 'Primera grabación', ja: 'はじめてのろくおん', ar: "أول تسجيل" },
  'Record your own voice reading a page.': { de: 'Nimm dich beim Vorlesen einer Seite auf.', fr: 'Enregistre ta voix en lisant une page.', es: 'Graba tu voz leyendo una página.', ja: '自分の声で1ページろくおんしよう。', ar: "سجّل صوتك وأنت تقرأ صفحة." },
  'First Book Made': { de: 'Erstes eigenes Buch', fr: 'Premier livre créé', es: 'Primer libro hecho', ja: 'はじめてつくった本', ar: "أول كتاب من صنعك" },
  'Make your own book in Make a Book.': { de: 'Mach mit „Buch machen“ dein eigenes Buch.', fr: 'Crée ton propre livre avec « Créer un livre ».', es: 'Haz tu propio libro con «Hacer un libro».', ja: '「えほんを つくる」で自分の本をつくろう。', ar: "اصنع كتابك الخاص في «اصنع كتابًا»." },
