  'Draw a picture in My Notes.': { de: 'Mal ein Bild in Meine Notizen.', fr: 'Dessine dans Mes notes.', es: 'Haz un dibujo en Mis notas.', ja: 'わたしの メモにえをかこう。', ar: "ارسم صورة في «ملاحظاتي»." },
  'Bedtime Read': { de: 'Gute-Nacht-Lesen', fr: 'Lecture du soir', es: 'Lectura de buenas noches', ja: 'おやすみまえのよみきかせ', ar: "قراءة قبل النوم" },
  'Read a book in the evening, after 7 o’clock.': { de: 'Lies abends nach 19 Uhr ein Buch.', fr: 'Lis un livre le soir, après 19 heures.', es: 'Lee un libro por la noche, después de las 7.', ja: 'よる7じすぎに本をよもう。', ar: "اقرأ كتابًا في المساء، بعد الساعة 7." },
