  'End of the recording': { de: 'Ende der Aufnahme', fr: 'Fin de l’enregistrement', es: 'Final de la grabación', ja: 'ろくおんの おわり', ar: "نهاية التسجيل" },
  'Who’s reading?': { de: 'Wer liest vor?', fr: 'Qui lit ?', es: '¿Quién lee?', ja: 'だれが よむ?', ar: "من يقرأ؟" },
  'Up to three people can record this book in their own voice. Pick who’s reading now, or add a new reader.': { de: 'Bis zu drei Personen können dieses Buch mit ihrer eigenen Stimme aufnehmen. Wähle, wer jetzt liest, oder füge jemanden hinzu.', fr: 'Jusqu’à trois personnes peuvent enregistrer ce livre avec leur propre voix. Choisis qui lit maintenant, ou ajoute un lecteur.', es: 'Hasta tres personas pueden grabar este libro con su propia voz. Elige quién lee ahora o añade a alguien.', ja: '3にんまで じぶんの こえで ろくおんできます。いま よむ ひとを えらぶか、あたらしく ついかしてね。', ar: "يمكن لثلاثة أشخاص كحدّ أقصى تسجيل هذا الكتاب بأصواتهم. اختر من يقرأ الآن، أو أضف قارئًا جديدًا." },
  'Add a reader': { de: 'Jemand Neues', fr: 'Ajouter un lecteur', es: 'Añadir a alguien', ja: 'よむ ひとを ついか', ar: "إضافة قارئ" },
