  "All classes": { de: "Alle Klassen", fr: "Toutes les classes", es: "Todas las clases", ja: "すべての クラス", ar: "كل الصفوف" },
  "Classes": { de: "Klassen", fr: "Classes", es: "Clases", ja: "クラス", ar: "الصفوف" },
  "Each class has its own folder, with up to {n} students. Tap a class to open it.": { de: "Jede Klasse hat ihren eigenen Ordner mit bis zu {n} Schülern. Tippe auf eine Klasse, um sie zu öffnen.", fr: "Chaque classe a son dossier, avec jusqu’à {n} élèves. Touchez une classe pour l’ouvrir.", es: "Cada clase tiene su carpeta, con hasta {n} alumnos. Toca una clase para abrirla.", ja: "クラスごとに フォルダが あり、{n}人まで はいれます。クラスを タップして ひらきます。", ar: "لكل صف مجلده، ويتّسع لما يصل إلى {n} طالبًا. اضغط على صف لفتحه." },
  "Tap profiles to select them.": { de: "Tippe auf Profile, um sie auszuwählen.", fr: "Touchez des profils pour les sélectionner.", es: "Toca perfiles para seleccionarlos.", ja: "プロフィールを タップして えらびます。", ar: "اضغط على الملفات لتحديدها." },
  "Grid": { de: "Raster", fr: "Grille", es: "Cuadrícula", ja: "ならべる", ar: "شبكة" },
  "List": { de: "Liste", fr: "Liste", es: "Lista", ja: "リスト", ar: "قائمة" },
