  "Cool": { de: "Kühl", fr: "Froid", es: "Frío", ja: "すずしい", ar: "بارد" },
  "Books you make together": { de: "Bücher, die ihr\nzusammen macht" /* always two lines, like the French (Jörg, 27 Oct 2026) */, fr: "Des livres que l’on\nfait ensemble", es: "Libros que hacéis juntos", ja: "いっしょに つくる えほん", ar: "كتب تصنعونها معًا" },
  "Pssst, here’s a hint. Taking photos of your paper drawings is a fun way to build a Coro book.": { de: "Psst, ein Tipp: Fotos von deinen Zeichnungen auf Papier sind eine tolle Art, ein Coro-Buch zu machen.", fr: "Psst, une astuce : prendre en photo tes dessins sur papier, c’est une super façon de créer un livre Coro.", es: "Psst, un consejo: hacer fotos de tus dibujos en papel es una forma divertida de crear un libro de Coro.", ja: "ないしょの ヒント。かみに かいた えを しゃしんに とると、たのしく Coro の 本が つくれるよ。", ar: "بسس. إليك تلميحًا: تصوير رسوماتك الورقية طريقة ممتعة لصنع كتاب Coro." },
  "Got it!": { de: "Alles klar!", fr: "Compris !", es: "¡Entendido!", ja: "わかった！", ar: "فهمت!" },
  "Take the tour": { de: "Tour starten", fr: "Faire la visite", es: "Hacer el recorrido", ja: "みてみる", ar: "ابدأ الجولة" },
  'Skip': { de: 'Überspringen', fr: 'Passer', es: 'Saltar', ja: 'スキップ', ar: "تخطٍّ" },
  'Back': { de: 'Zurück', fr: 'Retour', es: 'Atrás', ja: 'もどる', ar: "رجوع" },
